import type { PaymentMethod, Prisma } from '@prisma/client';
import { db } from '../../lib/db';

/**
 * Create a booking sale and (when a deposit is taken) its DEPOSIT receipt in
 * the caller's transaction. Shared by quotation → sale conversion and the
 * "จองรถ" mode of the payment page so both write the same rows:
 *   Sale (paidAmount = deposit, remaining = price − deposit)
 *   Payment DEPOSIT + ActivityLog CREATE_DEPOSIT_PAYMENT
 * Amounts come from `reservationAmounts`; numbers are pre-generated by the
 * caller outside the transaction (sequences survive a rollback).
 */
export async function createReservationWithDeposit(
  tx: Prisma.TransactionClient,
  args: {
    userId: string;
    sale: Omit<Prisma.SaleUncheckedCreateInput, 'createdById' | 'paidAmount'> & {
      saleNumber: string;
      customerId: string;
      depositAmount: number;
    };
    /** Omit (or pass null) to create the sale without a receipt. */
    deposit?: {
      receiptNumber: string;
      paymentDate: Date;
      paymentMethod: PaymentMethod;
      referenceNumber?: string | null;
      notes?: string | null;
      description?: string | null;
      receivingBank?: string | null;
      receivingBankName?: string | null;
      receivingAccountNumber?: string | null;
      receivingBranch?: string | null;
      issuedBy: string;
      /** Extra keys for the CREATE_DEPOSIT_PAYMENT log (e.g. quotationNumber). */
      logDetails?: Record<string, unknown>;
    } | null;
  }
) {
  const { userId, deposit } = args;
  const depositAmount = args.sale.depositAmount;
  const takesDeposit = depositAmount > 0 && !!deposit;

  const sale = await tx.sale.create({
    data: {
      ...args.sale,
      paidAmount: takesDeposit ? depositAmount : 0,
      createdById: userId,
    },
  });

  if (!takesDeposit) return { sale, payment: null };

  const payment = await tx.payment.create({
    data: {
      receiptNumber: deposit.receiptNumber,
      customerId: args.sale.customerId,
      saleId: sale.id,
      paymentDate: deposit.paymentDate,
      paymentType: 'DEPOSIT',
      amount: depositAmount,
      paymentMethod: deposit.paymentMethod,
      referenceNumber: deposit.referenceNumber || null,
      notes: deposit.notes || null,
      description: deposit.description || null,
      receivingBank: deposit.receivingBank || deposit.receivingBankName || null,
      receivingBankName: deposit.receivingBankName || null,
      receivingAccountNumber: deposit.receivingAccountNumber || null,
      receivingBranch: deposit.receivingBranch || null,
      createdById: userId,
      issuedBy: deposit.issuedBy,
    },
  });

  await tx.activityLog.create({
    data: {
      userId,
      action: 'CREATE_DEPOSIT_PAYMENT',
      entity: 'PAYMENT',
      entityId: sale.id,
      details: {
        saleNumber: sale.saleNumber,
        ...(deposit.logDetails ?? {}),
        depositAmount,
        paymentMethod: deposit.paymentMethod,
        receiptNumber: payment.receiptNumber,
      } as Prisma.InputJsonValue,
    },
  });

  return { sale, payment };
}

/**
 * The ACTIVE campaign covering this model on the sale's business day, if any.
 * The supplier-rebate report needs every eligible sale tagged; the
 * no-overlap rule guarantees at most one match (latest start wins for legacy
 * overlapping rows).
 */
export async function findActiveCampaignIdForModel(
  vehicleModelId: string,
  saleDay: Date
): Promise<string | undefined> {
  const campaign = await db.campaign.findFirst({
    where: {
      status: 'ACTIVE',
      startDate: { lte: saleDay },
      endDate: { gte: saleDay },
      vehicleModels: { some: { vehicleModelId } },
    },
    orderBy: { startDate: 'desc' },
    select: { id: true },
  });
  return campaign?.id;
}
